//! 快照打包配置

use std::path::{Path, PathBuf};

use zip::CompressionMethod;

use crate::{Error, ErrorKind, PackResult, Packer};

/// 快照打包配置
#[derive(Debug, Clone, Default)]
pub struct PackConfig {
    /// 压缩方式
    pub compression: CompressionMethod,
    /// 是否跟随符号链接遍历目录
    pub follow_symlinks: bool,
}

/// 快照打包进度汇报
///
/// 所有方法均在打包线程内同步调用, 汇报器需保证线程安全.
///
/// # Behavior
/// * 扫描或打包中遇到错误时, 汇报器返回 `true` 表示要求中断打包.
pub trait ProgressReporter: Send + Sync {
    /// 开始扫描
    fn on_scan_start(&self);

    /// 扫描到一个文件, 返回其路径, 序号 (从 1 开始) 与累计体积
    fn on_scan_file(&self, path: &Path, index: usize, cumulative_size: u64);

    /// 扫描中遇到错误, 询问是否中断
    fn on_scan_error(&self, error: &Error) -> bool;

    /// 扫描完成, 返回文件总数与总体积
    fn on_scan_complete(&self, count: usize, total_size: u64);

    /// 开始打包
    ///
    /// # Arguments
    /// * **files** - 按路径排序的待打包文件列表.
    /// * **total_size** - 待打包文件总体积.
    fn on_pack_start(&self, files: &[PathBuf], total_size: u64);

    /// 打包完一个文件
    ///
    /// # Arguments
    /// * **path** - 文件路径.
    /// * **index** - 已打包文件数 (从 1 开始).
    /// * **cumulative_size** - 已打包文件原始体积.
    /// * **cumulative_compressed_size** - 压缩包累计体积.
    fn on_pack_file(
        &self,
        path: &Path,
        index: usize,
        cumulative_size: u64,
        cumulative_compressed_size: u64,
    );

    /// 打包中遇到错误, 询问是否中断
    fn on_pack_error(&self, error: &Error) -> bool;

    /// 打包完成, 返回压缩包总体积
    fn on_pack_complete(&self, final_size: u64);
}

/// 快照打包构建器
#[derive(Default)]
pub struct PackerBuilder {
    source: Option<PathBuf>,
    destination: Option<PathBuf>,
    config: PackConfig,
    progress_reporter: Option<Box<dyn ProgressReporter>>,
}

impl PackerBuilder {
    /// 设置打包目录 (WebGAL 项目根目录, 包含 `game/` 子目录)
    pub fn source<P: Into<PathBuf>>(mut self, path: P) -> Self {
        self.source = Some(path.into());
        self
    }

    /// 设置输出位置 (压缩包文件路径, 已存在则覆盖)
    pub fn destination<P: Into<PathBuf>>(mut self, path: P) -> Self {
        self.destination = Some(path.into());
        self
    }

    /// 设置压缩方式
    pub fn compression(mut self, method: CompressionMethod) -> Self {
        self.config.compression = method;
        self
    }

    /// 跟随符号链接遍历目录
    pub fn follow_symlinks(mut self) -> Self {
        self.config.follow_symlinks = true;
        self
    }

    /// 设置进度汇报器
    pub fn with_progress<P: ProgressReporter + 'static>(mut self, reporter: P) -> Self {
        self.progress_reporter = Some(Box::new(reporter));
        self
    }

    /// 构建打包器
    ///
    /// # Behavior
    /// * 打包目录与输出位置会被转换为绝对路径.
    pub fn build(self) -> Result<Packer, ErrorKind> {
        let Self {
            source,
            destination,
            config,
            progress_reporter,
        } = self;

        let source = source.ok_or(ErrorKind::MissingSource)?;
        let destination = destination.ok_or(ErrorKind::MissingDestination)?;

        // 转换为绝对路径, 保证打包结果与错误信息中的路径一致
        let source = std::path::absolute(source).map_err(ErrorKind::Io)?;
        let destination = std::path::absolute(destination).map_err(ErrorKind::Io)?;

        Ok(Packer {
            source,
            destination,
            config,
            progress_reporter,
        })
    }

    /// 构建并执行快照打包
    pub fn run(self) -> PackResult {
        let packer = match self.build() {
            Ok(v) => v,
            Err(error) => {
                return PackResult {
                    errors: vec![error.into()],
                    ..Default::default()
                };
            }
        };
        packer.run()
    }
}
